(function initChart() {
  const GUID =  w.general.renderTo;//'f5b6c7454289472ea4d8ba2b249c25b4';

  function findContainer() {
    return document.getElementById(GUID)
        || document.getElementById('widget-' + GUID)
        || document.querySelector(`[id$="${GUID}"]`);
  }

  const chartDom = findContainer();
  if (!chartDom) {
    console.error('Контейнер виджета не найден в DOM:', GUID);
    return;
  }

  const existing = echarts.getInstanceByDom(chartDom);
  if (existing) existing.dispose();

  chartDom.innerHTML = '';
  chartDom.style.background = '#ffffff';
  chartDom.style.width = '100%';
  chartDom.style.height = '100%';
  chartDom.style.position = 'relative';
  chartDom.style.display = 'flex';
  chartDom.style.flexDirection = 'column';
  chartDom.style.padding = '16px 20px';
  chartDom.style.boxSizing = 'border-box';
  chartDom.style.fontFamily = "'Open Sans', -apple-system, sans-serif";

  //const titleEl = document.createElement('div');
  //titleEl.textContent = 'Прогноз подписанных контрактов';
  //titleEl.style.cssText = `
//      font-size: 14px;
//      font-weight: 400;
//      color: #7a8899;
//      line-height: 1.3;
//      padding-top: 2px;
//      flex-shrink: 0;
 // `;
  //chartDom.appendChild(titleEl);

  const chartBox = document.createElement('div');
  chartBox.style.cssText = 'flex: 1 1 auto; min-height: 0; width: 100%;';
  chartDom.appendChild(chartBox);

  // =========================================================
  // ★ ИСПРАВЛЕНИЕ: Принудительное добавление пустых сценариев
  // =========================================================
  // Впишите сюда те названия, которые приходят из системы (name или formattedName).
  // ВАЖНО: проверьте, как именно они называются в w.series[0].data (например: '0,5' или '0.5' или '50%')
  const EXPECTED_SCENARIOS = ['0,5', '1']; 

  const rawSeriesData = (w.series && w.series[0] && w.series[0].data) || [];

  // Формируем итоговый массив: берем ожидаемые сценарии и ищем их в пришедших данных
  const seriesData = EXPECTED_SCENARIOS.map(expectedName => {
      const found = rawSeriesData.find(d => {
          const name = String(d.formattedName ?? d.name ?? '').trim();
          // Проверяем совпадение (на случай разных разделителей)
          return name === expectedName || name === expectedName.replace(',', '.');
      });
      
      if (found) return found;
      // Если BI не прислал этот сценарий, создаем его вручную со значением 0
      return { name: expectedName, value: 0 };
  });

  // Если в данных есть какие-то ДРУГИЕ сценарии, не указанные в EXPECTED_SCENARIOS, 
  // мы их тоже добавим, чтобы не потерять (опционально)
  rawSeriesData.forEach(d => {
      const name = String(d.formattedName ?? d.name ?? '').trim();
      const isExpected = EXPECTED_SCENARIOS.some(exp => exp === name || exp.replace(',', '.') === name);
      if (!isExpected) seriesData.push(d);
  });

  if (!seriesData.length) {
    console.warn('Нет данных для отрисовки');
    return;
  }
  // =========================================================

  // Приведение к числу: null / "" / "0" → 0
  function toNumber(raw) {
    if (raw === '' || raw == null) return 0;
    if (typeof raw === 'number') return isFinite(raw) ? raw : 0;
    const cleaned = String(raw).replace(/\s/g, '').replace(',', '.');
    const n = Number(cleaned);
    return isFinite(n) ? n : 0;
  }

  function formatValue(raw) {
    if (raw === '' || raw == null) return '$0';
    if (typeof raw === 'string' && /[A-Za-z$€₽]/.test(raw)) return raw;
    const cleaned = String(raw).replace(/\s/g, '').replace(',', '.');
    const num = Number(cleaned);
    if (isNaN(num)) return String(raw);
    const abs  = Math.abs(num);
    const sign = num < 0 ? '-' : '';
    let formatted;
    if (abs >= 1e9)       formatted = (abs / 1e9).toFixed(1).replace(/\.0$/, '') + 'B';
    else if (abs >= 1e6)  formatted = (abs / 1e6).toFixed(1).replace(/\.0$/, '') + 'M';
    else if (abs >= 1e3)  formatted = (abs / 1e3).toFixed(1).replace(/\.0$/, '') + 'K';
    else                  formatted = abs.toString();
    return sign + '$' + formatted;
  }

  const values = seriesData.map(d => toNumber(d.value));
  const labels = values.map(v => formatValue(v));

  // Форматирование названий (Сценарий 100 %)
  function formatCategory(d, i) {
    const raw = d.formattedName ?? d.name;
    if (raw == null || raw === '') return 'Сценарий ' + i;

    const str = String(raw).trim();

    if (/^Сценарий\s+\d/.test(str)) return str;

    if (/%/.test(str)) {
      return /^Сценарий/i.test(str) ? str : 'Сценарий ' + str.replace(/\s*%/, ' %');
    }

    const num = Number(str.replace(/\s/g, '').replace(',', '.'));
    if (!isNaN(num)) {
      const pct = num <= 1 ? Math.round(num * 100) : Math.round(num);
      return `Сценарий ${pct} %`;
    }

    return /^Сценарий/i.test(str) ? str : 'Сценарий ' + str;
  }

  const categories = seriesData.map((d, i) => formatCategory(d, i));

  const BAR_COLORS = ['#1F4864', '#7BA3BD', '#4A7A9B', '#A8C4D6'];

  const chart = echarts.init(chartBox);

  const option = {
    backgroundColor: '#ffffff',

    grid: {
      left: 8,
      right: 8,
      top: 8,
      bottom: 8,
      containLabel: true
    },

    xAxis: {
      type: 'value',
      show: false,
      min: 0,
      max: (v) => Math.max(v.max, 1) // Не даем оси схлопнуться, если все значения 0
    },

    yAxis: {
      type: 'category',
      data: categories,
      show: true,
      inverse: true,
      axisLine:  { show: false },
      axisTick:  { show: false },
      splitLine: { show: false },
      axisLabel: {
        show: true,
        color: '#4a5a6a',
        fontSize: 12,
        fontFamily: "'Open Sans', Arial, sans-serif",
        margin: 10,
        width: 140,
        overflow: 'truncate',
        ellipsis: '…',
        align: 'right'
      }
    },

    tooltip: {
      trigger: 'item',
      backgroundColor: '#1e3d5c',
      borderWidth: 0,
      textStyle: { color: '#ffffff', fontSize: 12 },
      formatter: (p) => `${p.name}<br/><b>${labels[p.dataIndex]}</b>`
    },

    series: [{
      type: 'bar',
      barWidth: '75%',
      barCategoryGap: '25%',

      // ★ Рисуем серую дорожку на всю ширину для каждого бара
      showBackground: true,
      backgroundStyle: {
        color: '#eef2f6',
        borderRadius: 6
      },

      data: values.map((v, i) => {
        const isZero = v === 0;
        return {
          value: v,
          itemStyle: {
            // Если значение 0 — сам бар прозрачный, останется только серая дорожка
            color: isZero ? 'transparent' : BAR_COLORS[i % BAR_COLORS.length],
            borderRadius: 6
          },
          label: {
            show: true,
            // Для нуля подпись ставим снаружи (справа), иначе 0-ширинный бар её скроет
            position: isZero ? 'right' : 'inside',
            formatter: () => labels[i],
            color: isZero ? '#1e3d5c' : '#FFFFFF',
            fontSize: 16,
            fontWeight: 'bold',
            fontFamily: "'Open Sans', Arial, sans-serif",
            distance: isZero ? 8 : 5
          }
        };
      })
    }],
    animationDuration: 500
  };

  try {
    chart.setOption(option, true);
  } catch (e) {
    console.error('Ошибка setOption:', e);
  }

  if (window['__chartResize_' + GUID]) {
    window.removeEventListener('resize', window['__chartResize_' + GUID]);
  }
  window['__chartResize_' + GUID] = () => chart.resize();
  window.addEventListener('resize', window['__chartResize_' + GUID]);

  if (window['__chartRO_' + GUID]) {
    window['__chartRO_' + GUID].disconnect();
  }
  window['__chartRO_' + GUID] = new ResizeObserver(() => chart.resize());
  window['__chartRO_' + GUID].observe(chartBox);
})();

