(function () {
    const widgetId = w.general.renderTo;
    const container = document.getElementById(widgetId) || document.querySelector(`[id="${widgetId}"]`);
    if (!container) return;
    if (!w.series || !w.series[0] || !Array.isArray(w.series[0].data)) return;

    // =========================================================
    // 1. Фильтрация данных - только максимальный год
    // =========================================================
    const mainSeries = w.series[0];
    const originalData = mainSeries.data;
    
    let maxYear = null;
    const tempData = Array.isArray(originalData) ? originalData : (originalData[0] || []);
    
    tempData.forEach(point => {
        if (point && typeof point === "object" && point.name) {
            const dateMatch = String(point.name).match(/(\d{4})/);
            if (dateMatch) {
                const year = parseInt(dateMatch[1], 10);
                if (!maxYear || year > maxYear) {
                    maxYear = year;
                }
            }
        }
    });
    
    if (!maxYear) {
        tempData.forEach(point => {
            if (point && typeof point === "object" && point.id) {
                const dateMatch = String(point.id).match(/(\d{4})/);
                if (dateMatch) {
                    const year = parseInt(dateMatch[1], 10);
                    if (!maxYear || year > maxYear) {
                        maxYear = year;
                    }
                }
            }
        });
    }
    
    if (maxYear) {
        const filteredData = tempData.filter(point => {
            if (!point) return false;
            const nameStr = String(point.name || point.id || "");
            return nameStr.includes(String(maxYear));
        });
        
        if (filteredData.length > 0) {
            mainSeries.data = filteredData;
        }
    }

    // =========================================================
    // 2. Вспомогательные функции
    // =========================================================
    function getValue(point) {
        let value = point;
        if (point && typeof point === "object") {
            value = point.value !== undefined ? point.value : (point[point.length - 1] || 0);
        }
        if (Array.isArray(value)) value = value[value.length - 1];
        if (value === null || value === undefined || value === "") return 0;
        const result = Number(value);
        return Number.isFinite(result) ? result : 0;
    }

    function formatValue(value) {
        if (value >= 1000000) {
            return '$' + (value / 1000000).toFixed(2) + 'M';
        } else if (value >= 1000) {
            return '$' + (value / 1000).toFixed(2) + 'K';
        }
        return '$' + value.toFixed(2);
    }
    
    function escapeHTML(value) {
        return String(value).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&#39;");
    }

    // =========================================================
    // 3. Настройки контейнера
    // =========================================================
    const safeId = String(widgetId).replace(/[^a-zA-Z0-9_-]/g, "_");
    const className = "linechart-widget-" + safeId;
    container.classList.add(className);

    container.style.setProperty("position", "relative", "important");
    container.style.setProperty("background", "#ffffff", "important");
    container.style.setProperty("padding", "0", "important");
    container.style.setProperty("overflow", "visible", "important");
    container.style.setProperty("box-sizing", "border-box", "important");

    // =========================================================
    // 4. Настройки диаграммы
    // =========================================================
    w.general.backgroundColor = "transparent";
    w.general.padding = [0, 0, 0, 0];

    w.grid = {
        ...(w.grid || {}),
        left: 50,
        right: 30,
        top: 90,
        bottom: 40,
        containLabel: true
    };

    w.xAxis = {
        ...(w.xAxis || {}),
        type: "category",
        boundaryGap: false,
        axisLine: { show: true, lineStyle: { color: "#e0e6ed", width: 1 } },
        axisTick: { show: false },
        axisLabel: {
            show: true,
            color: "#718096",
            fontSize: 12,
            fontFamily: "Open Sans",
            margin: 12,
            formatter: function(value) {
                const months = {
                    'Январь': 'Янв', 'Февраль': 'Фев', 'Март': 'Мар',
                    'Апрель': 'Апр', 'Май': 'Май', 'Июнь': 'Июн',
                    'Июль': 'Июл', 'Август': 'Авг', 'Сентябрь': 'Сен',
                    'Октябрь': 'Окт', 'Ноябрь': 'Ноя', 'Декабрь': 'Дек',
                    'Jan': 'Янв', 'Feb': 'Фев', 'Mar': 'Мар',
                    'Apr': 'Апр', 'Jun': 'Июн', 'Jul': 'Июл',
                    'Aug': 'Авг', 'Sep': 'Сен', 'Oct': 'Окт',
                    'Nov': 'Ноя', 'Dec': 'Дек'
                };
                return months[value] || value;
            }
        },
        splitLine: { show: false }
    };

    w.yAxis = {
        ...(w.yAxis || {}),
        type: "value",
        axisLine: { show: false },
        axisTick: { show: false },
        axisLabel: {
            show: true,
            color: "#718096",
            fontSize: 12,
            fontFamily: "Open Sans",
            margin: 8,
            formatter: function(value) {
                if (value >= 1000000) {
                    return (value / 1000000).toFixed(1);
                } else if (value >= 1000) {
                    return (value / 1000).toFixed(0) + 'K';
                }
                return value;
            }
        },
        splitLine: {
            show: true,
            lineStyle: {
                color: "#e0e6ed",
                type: "solid",
                width: 1
            }
        }
    };

    mainSeries.type = "line";
    mainSeries.smooth = false;
    mainSeries.symbol = "circle";
    mainSeries.symbolSize = 8;
    mainSeries.lineStyle = {
        ...(mainSeries.lineStyle || {}),
        color: "#1e4c85",
        width: 3
    };
    mainSeries.itemStyle = {
        ...(mainSeries.itemStyle || {}),
        color: "#1e4c85",
        borderWidth: 2,
        borderColor: "#ffffff"
    };
    mainSeries.areaStyle = null;

    w.tooltip = {
        ...(w.tooltip || {}),
        show: true,
        trigger: "item",
        confine: true,
        backgroundColor: "#ffffff",
        borderColor: "#e0e6ed",
        borderWidth: 1,
        borderRadius: 8,
        padding: [12, 16],
        textStyle: {
            color: "#253342",
            fontSize: 12,
            fontFamily: "Open Sans, Arial, sans-serif"
        },
        extraCssText: "box-shadow:0 4px 20px rgba(30,61,92,0.13);min-width:280px;",
        formatter: function(params) {
            const value = getValue(params.data);
            const formattedValue = formatValue(value);
            
            let dateStr = params.name || "";
            if (typeof dateStr === "object" && dateStr !== null) {
                dateStr = dateStr.name || dateStr.id || "";
            }
            
            const intervalText = "Интервал первой успешной верификации: " + escapeHTML(dateStr) + ".";
            
            return `
                <div style="min-width:260px; color:#253342; font-size:12px; line-height:1.6;">
                    <div style="margin-bottom:6px; color:#153b63; font-weight:600;">${intervalText}</div>
                    <div><b>Верифицированный объем:</b> ${formattedValue}</div>
                </div>
            `;
        }
    };

    w.legend = {
        ...(w.legend || {}),
        show: true,
        top: 55,
        left: 0,
        itemWidth: 20,
        itemHeight: 3,
        textStyle: {
            color: "#153b63",
            fontSize: 13,
            fontFamily: "Open Sans",
            fontWeight: 600
        },
        icon: "line"
    };

    w.dataZoom = [];

    // =========================================================
    // 5. Отрисовка
    // =========================================================
    ChartRender({
        general: w.general,
        xAxis: w.xAxis,
        yAxis: w.yAxis,
        series: w.series,
        legend: w.legend,
        tooltip: w.tooltip,
        grid: w.grid,
        dataZoom: w.dataZoom
    });

    // =========================================================
    // 6. Добавление шапки и Info
    // =========================================================
    function setupLayout() {
        let chartDom = container.querySelector('[_echarts_instance_]');
        if (!chartDom) {
            const canvas = container.querySelector('canvas');
            if (canvas) chartDom = canvas.parentElement;
        }
        if (!chartDom) { setTimeout(setupLayout, 100); return; }

        if (!container.querySelector('.linechart-custom-header')) {
            const header = document.createElement("div");
            header.className = "linechart-custom-header";
            header.style.cssText = `
                position: absolute;
                top: 0; left: 0; right: 0;
                padding: 1px 80px 16px 20px;
                background: #ffffff;
                z-index: 1000;
                box-sizing: border-box;
                pointer-events: none;
            `;
            
            header.innerHTML = `
                <div style="color:#718096; font-family:'Open Sans',Arial,sans-serif; font-size:13px; line-height:1.3;">
                    Первое успешное завершение верификации
                </div>
            `;

            const info = document.createElement("div");
            info.className = "linechart-info-icon";
            info.style.cssText = `
                position: absolute; top: 24px; right: 20px; width: 18px; height: 18px;
                border-radius: 50%; border: 1.3px solid #7a8899; background: #ffffff;
                color: #7a8899; font-size: 11px; font-weight: 600; font-style: italic;
                display: flex; align-items: center; justify-content: center;
                cursor: pointer; pointer-events: auto; box-sizing: border-box; font-family: Georgia, serif;
                user-select: none; z-index: 200;
            `;
            info.textContent = "i";

            const infoTooltip = document.createElement("div");
            infoTooltip.style.cssText = `
                position: absolute; top: 26px; right: 0; width: 340px;
                background: #ffffff; border: 1px solid #e0e6ed; border-radius: 8px;
                box-shadow: 0 4px 20px rgba(30,61,92,0.15); padding: 16px 18px;
                font-size: 12px; color: #333; line-height: 1.5; display: none;
                text-align: left; font-weight: normal; z-index: 9999;
            `;
            infoTooltip.innerHTML = `
              <div style="margin-bottom:8px;">
                <strong>Методика расчета:</strong><br>
                Динамика объема впервые подписанных контрактов по дате первого подписания.
              </div>
            `;
            info.addEventListener("mouseenter", () => { infoTooltip.style.display = "block"; });
            info.addEventListener("mouseleave", () => { infoTooltip.style.display = "none"; });
            
            info.appendChild(infoTooltip);
            header.appendChild(info);
            container.insertBefore(header, container.firstChild);
        }
    }

    setTimeout(setupLayout, 50);
})();

