// -------- 1. Привязка серий к секциям и цветам --------
const SECTION_BY_SERIES = {
    'Конверсия Contracting':           'Contracting',
    'Win Rate Contracting, %':         'Contracting',
    'Конверсия Contract Verification': 'Contract Verification'
};

// Градиент [тёмный → светлый] для каждого бара.
// синий для Конверсий, зелёный для Win Rate.
const COLOR_PAIRS = {
    'Конверсия Contracting':           ['#1e4c85', '#4a90c2'],
    'Win Rate Contracting, %':         ['#0f6b4a', '#3aab7a'],
    'Конверсия Contract Verification': ['#1e4c85', '#4a90c2']
};

const TRACK_COLOR   = '#eef3f8';
const LABEL_COLOR   = '#5c7080';
const VALUE_COLOR   = '#1e3d5c';
const SECTION_COLOR = '#1e3d5c';

const BAR_HEIGHT = 14;
const RADIUS     = BAR_HEIGHT / 2;

// -------- 2. Собираем строки (заголовки секций + бары) --------
const rows = [];
const seen = new Set();
w.series.forEach(function (s) {
    const key = s.id || s.name;
    const section = SECTION_BY_SERIES[key] || SECTION_BY_SERIES[s.name];
    if (section && !seen.has(section)) {
        seen.add(section);
        rows.push({ type: 'header', label: section });
    }
    rows.push({ type: 'bar', series: s });
});

// -------- 3. Хелперы --------
function extractValue(s) {
    let v = s.data;
    if (Array.isArray(v)) {
        v = v[0];
        if (v && typeof v === 'object' && 'value' in v) v = v.value;
    }
    return v;
}

function formatPercent(raw) {
    if (raw == null || raw === '') return '';
    if (typeof raw === 'string') {
        const n = Number(raw.replace('%', '').replace(',', '.').trim());
        return isNaN(n) ? raw : n.toFixed(1) + '%';
    }
    const num = Number(raw);
    if (isNaN(num)) return String(raw);
    const pct = num > 1 ? num : num * 100;   // защита от "57.1" и "0.571"
    return pct.toFixed(1) + '%';
}

// -------- 4. Данные для серий --------
const yCategories = rows.map(r => r.type === 'header' ? r.label : r.series.name);

// Трек: полоса во всю ширину, null для заголовков
const trackData = rows.map(r => r.type === 'header' ? null : 1);

// Значения: pill-shaped бар с градиентом
const barData = rows.map(function (r) {
    if (r.type === 'header') return null;
    const key = r.series.id || r.series.name;
    const pair = COLOR_PAIRS[key] || [r.series.color, r.series.color];
    return {
        value: extractValue(r.series),
        itemStyle: {
            color: new echarts.graphic.LinearGradient(0, 0, 1, 0, [
                { offset: 0, color: pair[0] },
                { offset: 1, color: pair[1] }
            ]),
            borderRadius: RADIUS
        }
    };
});

// Невидимая серия полной ширины — чтобы проценты встали в одну колонку справа
const valueColData = rows.map(function (r, i) {
    if (r.type === 'header') return null;
    return {
        value: 1,
        itemStyle: { color: 'transparent' },
        label: {
            show: true,
            position: 'right',
            distance: 10,
            formatter: () => formatPercent(barData[i] && barData[i].value),
            color: VALUE_COLOR,
            fontWeight: 'bold',
            fontSize: 13
        }
    };
});

// -------- 5. Конфиг ECharts --------
const option = {
    grid: {
