                Конверсия и Win Rate используют разные выборки и могут различаться.
            </div>
        `;
        document.body.appendChild(tooltipEl);
    }

    // --- ЛОГИКА ПОКАЗА ТУЛТИПА ---
    infoEl.addEventListener('mouseenter', () => {
        const rect = infoEl.getBoundingClientRect();
        tooltipEl.style.display = 'block';
        
        let top = rect.bottom + 8;
        let left = rect.right - 340;
        
        if (left < 10) left = rect.left;
        if (left + 340 > window.innerWidth - 10) left = window.innerWidth - 350;
        if (top + tooltipEl.offsetHeight > window.innerHeight - 10) {
            top = rect.top - tooltipEl.offsetHeight - 8;
        }
        
        tooltipEl.style.top = top + 'px';
        tooltipEl.style.left = left + 'px';
    });
    
    infoEl.addEventListener('mouseleave', () => {
        tooltipEl.style.display = 'none';
    });

    // --- СОЗДАЕМ КОНТЕЙНЕР ДЛЯ ГРАФИКА ---
    const chartEl = document.createElement('div');
