    const mainSeries = w.series[0];
    const originalData = mainSeries.data;

    function getValue(point) {
        let value = point;
        if (point && typeof point === "object") value = point.value;
        if (Array.isArray(value)) value = value[value.length - 1];
        if (value === null || value === undefined || value === "") return 0;
        const result = Number(value);
        return Number.isFinite(result) ? result : 0;
    }

    function getName(point, index) {
        if (point && typeof point === "object") {
            if (point.name != null && point.name !== "") return String(point.name);
            if (point.id != null && point.id !== "") return String(point.id);
        }
        if (Array.isArray(w.yAxis?.data) && w.yAxis.data[index] != null) {
            return String(w.yAxis.data[index]);
        }
        return String(index + 1);
    }

    function formatValue(value) {
        return new Intl.NumberFormat("ru-RU", { maximumFractionDigits: 2 }).format(value);
    }

    function escapeHTML(value) {
        return String(value).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&#39;");
    }

    // ---- СОРТИРОВКА по убыванию значения ----
    // Сортируем сразу "пары" (оригинальная точка + имя + значение),
    // затем раскладываем обратно в rows и в w.series[0].data,
    // чтобы подписи и длины баров остались синхронными.
    const indexed = originalData.map((point, index) => ({
        original: point,
        name: getName(point, index),
        value: getValue(point)
    }));
    indexed.sort((a, b) => b.value - a.value);

    const rows = indexed.map(x => ({ name: x.name, value: x.value }));
    w.series[0].data = indexed.map(x => x.original);

    const count = rows.length;
    if (count === 0) {
        container.innerHTML = '<div style="padding:20px;color:#718096;font-family:\'Open Sans\',Arial,sans-serif;">Нет данных</div>';
        return;
    }

    const maxValue = Math.max(1, ...rows.map(row => row.value));
    const axisMax = maxValue * 1.16;

    // =========================================================
    // 2. Дата (без изменений)
    // =========================================================
    let cachedPeriodEnd = null;
    let apiLookupStarted = false;

    function readDateDirect(object) {
        if (!object || typeof object !== "object") return null;
        const candidates = [
            object, object.DataGridOptions, object.dataGridOptions, object.options,
            object.options?.DataGridOptions, object.options?.dataGridOptions
        ];
        for (const candidate of candidates) {
            const value = candidate?.dataSource?._items?.[0]?.SelectedPeriodEnd;
            if (value !== undefined && value !== null && value !== "") return value;
        }
        return null;
    }

    function findDateDeep(root, maxDepth = 6) {
        const direct = readDateDirect(root);
        if (direct != null) return direct;
        if (!root || typeof root !== "object") return null;
        const queue = [{ object: root, depth: 0 }];
        const visited = new WeakSet();
        let checked = 0;
        while (queue.length && checked < 1500) {
            const item = queue.shift();
            const object = item.object;
            if (!object || typeof object !== "object") continue;
            if (visited.has(object)) continue;
            visited.add(object);
            checked++;
            const value = readDateDirect(object);
            if (value != null) return value;
            if (item.depth >= maxDepth || object.nodeType) continue;
            let keys;
            try { keys = Object.keys(object); } catch (_) { continue; }
            for (const key of keys) {
                if (["parent", "parentNode", "ownerDocument", "element", "children"].includes(key)) continue;
                let child;
                try { child = object[key]; } catch (_) { continue; }
                if (child && typeof child === "object") {
                    queue.push({ object: child, depth: item.depth + 1 });
                }
            }
        }
        return null;
    }

    function getPeriodEndRaw() {
        try {
            if (typeof DataGridOptions !== "undefined") {
                const value = readDateDirect(DataGridOptions);
                if (value != null) { cachedPeriodEnd = value; return value; }
            }
        } catch (_) {}
        try {
            const value = readDateDirect(window.DataGridOptions);
            if (value != null) { cachedPeriodEnd = value; return value; }
        } catch (_) {}
        try {
            const gridElement = document.getElementById("dataGridContainer_" + DATE_WIDGET_ID);
            if (gridElement) {
                const candidates = [gridElement.DataGridOptions, gridElement.dataGridOptions, gridElement.__DataGridOptions, gridElement.ej2_instances?.[0]];
                for (const candidate of candidates) {
                    const value = findDateDeep(candidate, 4);
                    if (value != null) { cachedPeriodEnd = value; return value; }
                }
            }
        } catch (_) {}

        if (!apiLookupStarted && typeof visApi === "function") {
            apiLookupStarted = true;
            try {
                const sourceWidget = visApi().getWidgetByGuid(DATE_WIDGET_ID);
                if (sourceWidget && typeof sourceWidget.then === "function") {
                    sourceWidget.then(function (object) {
                        const value = findDateDeep(object);
                        if (value != null) cachedPeriodEnd = value;
                    }).catch(function (error) { console.warn("Ошибка даты:", error); });
                } else {
                    const value = findDateDeep(sourceWidget);
                    if (value != null) { cachedPeriodEnd = value; return value; }
                }
            } catch (error) { console.warn("Ошибка чтения даты:", error); }
        }
        return cachedPeriodEnd;
    }

    function formatDate(value) {
        if (value === null || value === undefined || value === "") return "—";
        if (typeof value === "string") {
            const match = value.match(/^(\d{4})-(\d{2})-(\d{2})/);
            if (match) return `${match[3]}.${match[2]}.${match[1]}`;
        }
        const date = value instanceof Date ? value : new Date(value);
        if (Number.isNaN(date.getTime())) return String(value);
        const day = String(date.getDate()).padStart(2, "0");
        const month = String(date.getMonth() + 1).padStart(2, "0");
        return `${day}.${month}.${date.getFullYear()}`;
    }

    // =========================================================
    // 3. Константы layout
    // =========================================================
    const BAR_HEIGHT      = 24;
    const GAP             = 10;
    const CATEGORY_HEIGHT = BAR_HEIGHT + GAP;          // 34 px на строку
    const HEADER_HEIGHT   = 60;

    const exactChartHeight = count * CATEGORY_HEIGHT;  // 3 бара → 102, 20 баров → 680

    // =========================================================
    // 4. Стили контейнера
    // =========================================================
    const safeId = String(widgetId).replace(/[^a-zA-Z0-9_-]/g, "_");
    container.classList.add("verification-widget-" + safeId);

    container.style.setProperty("position", "relative", "important");
    container.style.setProperty("background", "#ffffff", "important");
    container.style.setProperty("padding", "0", "important");
    container.style.setProperty("overflow", "hidden", "important");
    container.style.setProperty("box-sizing", "border-box", "important");
    container.style.setProperty("height", "100%", "important");
    container.style.setProperty("width", "100%", "important");

    if (container.parentElement) {
        container.parentElement.style.setProperty("overflow", "hidden", "important");
    }

    // =========================================================
    // 5. Конфиг ECharts
    //    grid.height = ровно высота chartDom → бары заполняют его целиком.
    // =========================================================
    w.general.backgroundColor = "transparent";
    w.general.padding = [0, 0, 0, 0];

    w.grid = {
        ...(w.grid || {}),
        left: 250,
        right: 65,
        top: 0,
        bottom: 0,
        height: exactChartHeight,
        containLabel: false
    };

    w.xAxis = { ...(w.xAxis || {}), type: "value", min: 0, max: axisMax, show: false, boundaryGap: [0, 0] };

    w.yAxis = {
        ...(w.yAxis || {}),
        type: "category",
        data: rows.map(row => row.name),
        inverse: true,
        boundaryGap: true,
        axisLine: { show: false },
        axisTick: { show: false },
        axisLabel: { show: true, color: "#102d4d", fontSize: 13, fontFamily: "Open Sans", width: 250, overflow: "truncate", align: "right", margin: 5 },
        splitLine: { show: false }
    };

    mainSeries.type = "bar";
    mainSeries.barWidth = BAR_HEIGHT;
    delete mainSeries.barCategoryGap;
    delete mainSeries.barGap;
    mainSeries.showBackground = true;
    mainSeries.backgroundStyle = { color: "#f2f6fa", borderRadius: 6 };
    mainSeries.itemStyle = { ...(mainSeries.itemStyle || {}), color: "#1e4c85", borderRadius: 6 };
    mainSeries.label = {
        ...(mainSeries.label || {}),
        show: true, position: "right", distance: 40,
        color: "#102d4d", fontSize: 13, fontFamily: "Open Sans", fontWeight: 700,
