    };

    w.legend = { ...(w.legend || {}), show: false };

    w.tooltip = {
        ...(w.tooltip || {}),
        show: true, trigger: "item", confine: true,
        backgroundColor: "#ffffff", borderColor: "#dce3eb", borderWidth: 1,
        borderRadius: 9, padding: [12, 16],
        textStyle: { color: "#253342", fontSize: 12, fontFamily: "Open Sans, Arial, sans-serif" },
