        formatter: function (params) {
            if (Array.isArray(params)) params = params[0];
            const index = params && params.dataIndex != null ? params.dataIndex : 0;
            const row = rows[index] || { name: params?.name || "", value: getValue(params?.data) };
            const stageName = escapeHTML(params?.name || row.name);
            const contracts = formatValue(params && params.data !== undefined ? getValue(params.data) : row.value);
            const selectedDate = formatDate(getPeriodEndRaw());
            return `
                <div style="min-width:260px; max-width:330px; color:#253342; font-size:12px; line-height:1.5; white-space:normal;">
                    <div style="margin-bottom:3px;"><b>Стрим:</b> ${stageName}</div>
                    <div style="margin-bottom:3px;"><b>Верифицированный объем:</b> $${contracts}</div>
                    <div><b>На период:</b> ${escapeHTML(selectedDate)}.</div>
                    <div style="margin-top:8px;">Нажмите, чтобы применить отбор.</div>
                </div>
            `;
        }
    };
    w.dataZoom = [];

    // =========================================================
    // 6. Рендер встроенным рендерером
    // =========================================================
    BarChartRender({
        general: w.general, xAxis: w.xAxis, yAxis: w.yAxis,
        series: w.series, legend: w.legend, tooltip: w.tooltip,
        grid: w.grid, dataZoom: w.dataZoom
    });

    // =========================================================
    // 7. Шапка
    // =========================================================
    if (!container.querySelector(".verification-custom-header")) {
        const header = document.createElement("div");
        header.className = "verification-custom-header";
        header.style.cssText = `
            position: absolute;
            top: 0; left: 0; right: 0;
            height: ${HEADER_HEIGHT}px;
            padding: 1px 20px 8px 20px;
            background: #ffffff;
            z-index: 1000;
            box-sizing: border-box;
            pointer-events: none;
        `;
        header.innerHTML = `

            <div style="color:#718096; font-family:'Open Sans',Arial,sans-serif; font-size:12px; margin-top:4px; line-height:1.3;">
                На дату последней загрузки
            </div>
        `;

        const info = document.createElement("div");
        info.className = "verification-info-icon";
        info.style.cssText = `
            position: absolute; top: 12px; right: 16px; width: 18px; height: 18px;
            border-radius: 50%; border: 1.3px solid #7a8899; background: #ffffff;
            color: #7a8899; font-size: 11px; font-weight: 600; font-style: italic;
            display: flex; align-items: center; justify-content: center;
            cursor: pointer; pointer-events: auto; box-sizing: border-box; font-family:'Open Sans', Arial, sans-serif;
            user-select: none; z-index: 200;
        `;
        info.textContent = "i";

        // --- ВЫНОСИМ ТУЛТИП В BODY, ЧТОБЫ ОН НЕ ОБРЕЗАЛСЯ ---
        let infoTooltip = document.getElementById("verification-tooltip-" + safeId);
        if (!infoTooltip) {
            infoTooltip = document.createElement("div");
            infoTooltip.id = "verification-tooltip-" + safeId;
            infoTooltip.style.cssText = `
                position: fixed; width: 320px;
                background: #ffffff; border: 1px solid #e0e6ed; border-radius: 8px;
                box-shadow: 0 4px 20px rgba(30,61,92,0.15); padding: 16px 18px;
                font-size: 11px; color: #333; line-height: 1.45; display: none;
                text-align: left; font-weight: normal; z-index: 9999999;
                box-sizing: border-box; pointer-events: none; font-family: 'Open Sans', -apple-system, sans-serif
            `;
            infoTooltip.innerHTML = `
                <div style="margin-bottom:8px;">
                    <strong>Методика расчета:</strong><br>
                   Объем впервые подписанных контрактов по категории продукта или продуктовому стриму.
                    Сумма и разрез определяются на дату первого подписания каждого контракта. <br>
                    <strong>Сортировка:</strong> По убыванию объема на каждом уровне. <br>
                    <strong>Взаимодействие:</strong> Нажатие на строку устанавливает соответствующий общий фильтр и обновляет связанные объекты.
                </div>
            `;
            document.body.appendChild(infoTooltip);
        }

        // Умное позиционирование при наведении
        info.addEventListener("mouseenter", () => {
            const rect = info.getBoundingClientRect();
            infoTooltip.style.display = "block";
            
            // По умолчанию показываем внизу справа от иконки
            let top = rect.bottom + 8;
            let left = rect.right - 320;
            
            // Защита от выхода за левый край экрана
            if (left < 10) left = rect.left;
            // Защита от выхода за правый край экрана
            if (left + 320 > window.innerWidth - 10) left = window.innerWidth - 330;
            // Защита от выхода за нижний край (показываем сверху)
            if (top + infoTooltip.offsetHeight > window.innerHeight - 10) {
                top = rect.top - infoTooltip.offsetHeight - 8;
            }
            
            infoTooltip.style.top = top + "px";
            infoTooltip.style.left = left + "px";
        });
        
        info.addEventListener("mouseleave", () => {
            infoTooltip.style.display = "none";
        });

        // Добавляем иконку в шапку (сам тултип уже в body)
        header.appendChild(info);
        container.insertBefore(header, container.firstChild);
    }

    // =========================================================
    // 8. Утилиты layout
    // =========================================================
    function getEChartsInstance(dom) {
        const libs = [
            (typeof echarts !== "undefined" ? echarts : null),
            window.echarts,
            w.echarts
        ];
        for (const lib of libs) {
            if (lib && typeof lib.getInstanceByDom === "function") {
                try {
                    const inst = lib.getInstanceByDom(dom);
                    if (inst) return inst;
                } catch (_) {}
            }
        }
        return null;
    }

    function findChartDom() {
        let dom = container.querySelector("[_echarts_instance_]");
        if (dom) return dom;
        const canvas = container.querySelector("canvas");
        if (canvas && canvas.parentElement) return canvas.parentElement;
        const svg = container.querySelector("svg");
        if (svg && svg.parentElement) return svg.parentElement;
        return null;
    }

    function getContainerHeight() {
        let h = container.clientHeight;
        if (h > 0) return h;
        if (container.parentElement) {
            h = container.parentElement.clientHeight;
            if (h > 0) return h;
        }
        const rect = container.getBoundingClientRect();
        return rect.height > 0 ? Math.floor(rect.height) : 0;
    }

    // =========================================================
    // 9. Layout
    // =========================================================
    function setupLayout() {
        const chartDom = findChartDom();
        if (!chartDom) { setTimeout(setupLayout, 100); return; }

        const totalHeight = getContainerHeight();
        const availableHeight = totalHeight - HEADER_HEIGHT;
        if (availableHeight <= 0) { setTimeout(setupLayout, 150); return; }

        // --- ключевое: обсервер будет читать эти поля, а не замыкания ---
        container.__verificationChartDom    = chartDom;
        container.__verificationChartHeight = exactChartHeight;

        const needsScroll = exactChartHeight > availableHeight;

        let scrollWrapper = container.querySelector(".verification-scroll-wrapper");
        if (!scrollWrapper) {
            scrollWrapper = document.createElement("div");
            scrollWrapper.className = "verification-scroll-wrapper";
            container.appendChild(scrollWrapper);
        }

        // скролл включаем ТОЛЬКО когда контент реально больше видимой области
        scrollWrapper.style.cssText = `
            position: absolute;
            top: ${HEADER_HEIGHT}px;
            left: 0; right: 0; bottom: 0;
            overflow-y: ${needsScroll ? "auto" : "hidden"};
            overflow-x: hidden;
            box-sizing: border-box;
            display: flex;
            flex-direction: column;
            justify-content: ${needsScroll ? "flex-start" : "center"};
        `;

        if (chartDom.parentNode !== scrollWrapper) {
            scrollWrapper.appendChild(chartDom);
        }

        // важно: overflow:hidden на chartDom — чтобы канвас внутри не вылез
        // и не включил внешний скролл, если ECharts не успел перерисоваться
        chartDom.style.setProperty("overflow",   "hidden", "important");
        chartDom.style.setProperty("height",     exactChartHeight + "px", "important");
        chartDom.style.setProperty("min-height", exactChartHeight + "px", "important");
        chartDom.style.setProperty("max-height", exactChartHeight + "px", "important");
        chartDom.style.setProperty("width", "100%", "important");

        // ---- принудительный resize ECharts, чтобы канвас точно стал нужного размера ----
        const forceResize = () => {
            try {
                const inst = getEChartsInstance(chartDom) || getEChartsInstance(container);
                if (inst && typeof inst.resize === "function") {
                    inst.resize({ width: container.clientWidth, height: exactChartHeight });
                    return;
                }
            } catch (_) {}
            try { window.dispatchEvent(new Event("resize")); } catch (_) {}
        };
        forceResize();
        setTimeout(forceResize, 50);
        setTimeout(forceResize, 200);
        setTimeout(forceResize, 500);

        // ---- обсервер: восстановить высоту, если платформа/BarChartRender её перезапишет ----
        if (!container.__verificationObserver) {
            container.__verificationObserver = new MutationObserver((mutations) => {
                const dom    = container.__verificationChartDom;
                const target = container.__verificationChartHeight;
                if (!dom || !target || !dom.isConnected) return;

                for (const m of mutations) {
                    if (m.target !== dom || m.attributeName !== "style") continue;
                    if (dom.style.height !== target + "px") {
                        dom.style.setProperty("height",     target + "px", "important");
                        dom.style.setProperty("min-height", target + "px", "important");
                        dom.style.setProperty("max-height", target + "px", "important");
                        try {
                            const inst = getEChartsInstance(dom) || getEChartsInstance(container);
                            if (inst && typeof inst.resize === "function") {
                                inst.resize({ width: container.clientWidth, height: target });
                            }
                        } catch (_) {}
                    }
                }
            });
            container.__verificationObserver.observe(container, {
                attributes: true, subtree: true, attributeFilter: ["style"]
            });
        }
    }

    setTimeout(setupLayout, 50);

    // ---- пересчёт при изменении размера виджета ----
    if (typeof ResizeObserver !== "undefined" && !container.__verificationResizeObserver) {
        let resizeTimer = null;
        container.__verificationResizeObserver = new ResizeObserver(() => {
            if (resizeTimer) clearTimeout(resizeTimer);
            resizeTimer = setTimeout(setupLayout, 80);
        });
        container.__verificationResizeObserver.observe(container);
    }
})();

const widgetId = w.general.renderTo;
const widget = document.getElementById(widgetId);

const optionsInfoArr = [
    { name: "Категория продукта", value: "widget-1cc273d6aeea41d98e36c16a3053a62c" },
    { name: "Продуктовый стрим", value: "widget-b9ceacfb15f84f1ba67ee081e9fab48d" },
];

const cords = { left: 32, top: 712 };

// =========================================================
// 1. Сохраняем состояние в window, чтобы Visiology не сбрасывала выбор
// =========================================================
if (!window.__dropdown_states) window.__dropdown_states = {};
const stateKey = 'dropdown_' + optionsInfoArr.map(o => o.value).join('_');

if (!window.__dropdown_states[stateKey]) {
    window.__dropdown_states[stateKey] = optionsInfoArr[0].value;
}
const activeValue = window.__dropdown_states[stateKey];

// =========================================================
// 2. HTML
// =========================================================
widget.innerHTML = `
    <div id="dropdown-container-${widgetId}" style="margin-top: 3px;">
        <select id="dropdown-${widgetId}" class="chart-dropdown"></select>
    </div>
`;

// =========================================================
// 3. CSS + Динамические классы позиционирования
// =========================================================
const style = document.createElement('style');
let dynamicCss = `
    .chart-dropdown {
        width: 100%;
        height: 32px;
        background: white;
        color: black;
        border: 1px solid gray;
        border-radius: 5px;
        font-size: 16px;
        padding: 0 8px;
        cursor: pointer;
        transition-duration: 0.3s;
        outline: none;
    }
    .chart-dropdown:hover,
    .chart-dropdown:focus {
        border-color: black;
    }
    
    /* Класс для скрытия неактивных виджетов */
    .vis-widget-hidden {
        left: -2000px !important;
        top: -2000px !important;
        opacity: 0 !important;
        pointer-events: none !important;
    }
`;

optionsInfoArr.forEach(opt => {
    const safeId = opt.value.replace(/[^a-zA-Z0-9]/g, '_');
    opt.posClass = `vis-pos-${safeId}`;
    dynamicCss += `
        .${opt.posClass} {
            left: ${cords.left}px !important;
            top: ${cords.top}px !important;
            opacity: 1 !important;
            pointer-events: auto !important;
        }
    `;
});

style.innerHTML = dynamicCss;
document.head.appendChild(style);

// =========================================================
// 4. Заполняем <select>
// =========================================================
const select = document.getElementById(`dropdown-${widgetId}`);
optionsInfoArr.forEach(opt => {
    const option = document.createElement('option');
    option.value = opt.value;
    option.innerText = opt.name;
    select.appendChild(option);
});

// Устанавливаем сохраненное значение
select.value = activeValue;

// =========================================================
// 5. Логика переключения классов
// =========================================================
let isApplying = false;

function applyClasses() {
    if (isApplying) return;
    isApplying = true;
    
    const active = window.__dropdown_states[stateKey];
    
    optionsInfoArr.forEach(opt => {
        const chart = document.getElementById(opt.value);
        if (!chart) return;
        
        if (opt.value === active) {
            if (chart.classList.contains('vis-widget-hidden')) chart.classList.remove('vis-widget-hidden');
            if (!chart.classList.contains(opt.posClass)) chart.classList.add(opt.posClass);
        } else {
            if (chart.classList.contains(opt.posClass)) chart.classList.remove(opt.posClass);
            if (!chart.classList.contains('vis-widget-hidden')) chart.classList.add('vis-widget-hidden');
        }
    });
    
    // Освобождаем блокировку после того, как браузер переварил изменения
    setTimeout(() => { isApplying = false; }, 50);
}

// =========================================================
// 6. Обработчик изменения select
// =========================================================
select.onchange = function () {
    window.__dropdown_states[stateKey] = this.value;
    applyClasses();
};

// =========================================================
// 7. Защита от сброса Visiology (MutationObserver)
// =========================================================
const observer = new MutationObserver(() => {
    // Если Visiology сбросила классы или изменила стили — мгновенно возвращаем
    applyClasses();
});

function setupObserver() {
    observer.disconnect();
    optionsInfoArr.forEach(opt => {
