    function getEChartsInstance(dom) {
        const libs = [
            (typeof echarts !== "undefined" ? echarts : null),
            window.echarts,
            w.echarts
        ];
        for (const lib of libs) {
            if (lib && typeof lib.getInstanceByDom === "function") {
                try {
                    const inst = lib.getInstanceByDom(dom);
                    if (inst) return inst;
                } catch (_) {}
            }
        }
        return null;
    }

    function findChartDom() {
        let dom = container.querySelector("[_echarts_instance_]");
        if (dom) return dom;
        const canvas = container.querySelector("canvas");
        if (canvas && canvas.parentElement) return canvas.parentElement;
        const svg = container.querySelector("svg");
        if (svg && svg.parentElement) return svg.parentElement;
        return null;
    }

    function getContainerHeight() {
        let h = container.clientHeight;
        if (h > 0) return h;
        if (container.parentElement) {
            h = container.parentElement.clientHeight;
            if (h > 0) return h;
        }
        const rect = container.getBoundingClientRect();
        return rect.height > 0 ? Math.floor(rect.height) : 0;
    }

    // =========================================================
    // 9. Layout
    // =========================================================
    function setupLayout() {
        const chartDom = findChartDom();
        if (!chartDom) { setTimeout(setupLayout, 100); return; }

        const totalHeight = getContainerHeight();
        const availableHeight = totalHeight - HEADER_HEIGHT;
        if (availableHeight <= 0) { setTimeout(setupLayout, 150); return; }

        // --- ключевое: обсервер будет читать эти поля, а не замыкания ---
        container.__verificationChartDom    = chartDom;
        container.__verificationChartHeight = exactChartHeight;

        const needsScroll = exactChartHeight > availableHeight;

        let scrollWrapper = container.querySelector(".verification-scroll-wrapper");
        if (!scrollWrapper) {
            scrollWrapper = document.createElement("div");
            scrollWrapper.className = "verification-scroll-wrapper";
            container.appendChild(scrollWrapper);
        }

        // скролл включаем ТОЛЬКО когда контент реально больше видимой области
        scrollWrapper.style.cssText = `
            position: absolute;
            top: ${HEADER_HEIGHT}px;
            left: 0; right: 0; bottom: 0;
            overflow-y: ${needsScroll ? "auto" : "hidden"};
            overflow-x: hidden;
            box-sizing: border-box;
            display: flex;
            flex-direction: column;
            justify-content: ${needsScroll ? "flex-start" : "center"};
        `;

        if (chartDom.parentNode !== scrollWrapper) {
            scrollWrapper.appendChild(chartDom);
        }

        // важно: overflow:hidden на chartDom — чтобы канвас внутри не вылез
        // и не включил внешний скролл, если ECharts не успел перерисоваться
        chartDom.style.setProperty("overflow",   "hidden", "important");
        chartDom.style.setProperty("height",     exactChartHeight + "px", "important");
        chartDom.style.setProperty("min-height", exactChartHeight + "px", "important");
        chartDom.style.setProperty("max-height", exactChartHeight + "px", "important");
        chartDom.style.setProperty("width", "100%", "important");

        // ---- принудительный resize ECharts, чтобы канвас точно стал нужного размера ----
        const forceResize = () => {
            try {
                const inst = getEChartsInstance(chartDom) || getEChartsInstance(container);
                if (inst && typeof inst.resize === "function") {
                    inst.resize({ width: container.clientWidth, height: exactChartHeight });
                    return;
                }
            } catch (_) {}
            try { window.dispatchEvent(new Event("resize")); } catch (_) {}
        };
        forceResize();
        setTimeout(forceResize, 50);
        setTimeout(forceResize, 200);
        setTimeout(forceResize, 500);

        // ---- обсервер: восстановить высоту, если платформа/BarChartRender её перезапишет ----
        if (!container.__verificationObserver) {
            container.__verificationObserver = new MutationObserver((mutations) => {
                const dom    = container.__verificationChartDom;
                const target = container.__verificationChartHeight;
                if (!dom || !target || !dom.isConnected) return;

                for (const m of mutations) {
                    if (m.target !== dom || m.attributeName !== "style") continue;
                    if (dom.style.height !== target + "px") {
                        dom.style.setProperty("height",     target + "px", "important");
                        dom.style.setProperty("min-height", target + "px", "important");
                        dom.style.setProperty("max-height", target + "px", "important");
                        try {
                            const inst = getEChartsInstance(dom) || getEChartsInstance(container);
                            if (inst && typeof inst.resize === "function") {
                                inst.resize({ width: container.clientWidth, height: target });
                            }
                        } catch (_) {}
                    }
                }
            });
            container.__verificationObserver.observe(container, {
                attributes: true, subtree: true, attributeFilter: ["style"]
            });
        }
    }

    setTimeout(setupLayout, 50);

    // ---- пересчёт при изменении размера виджета ----
    if (typeof ResizeObserver !== "undefined" && !container.__verificationResizeObserver) {
        let resizeTimer = null;
        container.__verificationResizeObserver = new ResizeObserver(() => {
            if (resizeTimer) clearTimeout(resizeTimer);
            resizeTimer = setTimeout(setupLayout, 80);
        });
        container.__verificationResizeObserver.observe(container);
    }
})();

