            btnClear.style.display = 'none';
            btnChevron.style.display = 'none';
            return;
        }
        btnChevron.style.display = '';

        if (selectedIds.length === 0) {
            btnText.textContent = 'Все';
            btnClear.style.display = 'none';
        } else if (selectedIds.length === 1) {
            const c = items.find(i => i.id === selectedIds[0]);
            btnText.textContent = c ? itemName(c) : 'Все';
            btnClear.style.display = 'flex';
        } else {
            btnText.textContent = 'Выбрано: ' + selectedIds.length;
            btnClear.style.display = 'flex';
        }
    }
    updateButtonLabel();

    // ---------- 6. Dropdown ----------
    const dropdown = document.createElement('div');
    dropdown.className = 'cf2-dropdown';

    // Пункт «Все»
    const allItem = document.createElement('div');
    allItem.className = 'cf2-item cf2-all' +
        (selectedIds.length === 0 ? ' cf2-selected' : '');
    allItem.textContent = 'Все';
    allItem.dataset.value = '__ALL__';
    allItem.addEventListener('click', function (e) {
        e.stopPropagation();
        selectedIds = [];
        dropdown.querySelectorAll('.cf2-item')
                .forEach(i => i.classList.remove('cf2-selected'));
        allItem.classList.add('cf2-selected');
        updateButtonLabel();
        closeDropdown();
        applyFilter([]);
    });
    dropdown.appendChild(allItem);

    // Остальные пункты
    items.forEach(function (item) {
        const el = document.createElement('div');
        const isSel = selectedIds.indexOf(item.id) !== -1;
        el.className = 'cf2-item' + (isSel ? ' cf2-selected' : '');
        el.textContent = itemName(item);
        el.dataset.value = item.id;
        el.addEventListener('click', function (e) {
            e.stopPropagation();
            const selNow = selectedIds.indexOf(item.id) !== -1;

            if (selNow) {
                // Унселект — клик по выбранному снимает выбор
                selectedIds = selectedIds.filter(x => x !== item.id);
                el.classList.remove('cf2-selected');
                if (selectedIds.length === 0) allItem.classList.add('cf2-selected');
            } else {
                // Селект — одиночный выбор заменяет предыдущий
                selectedIds = [item.id];
                dropdown.querySelectorAll('.cf2-item')
                        .forEach(i => i.classList.remove('cf2-selected'));
                allItem.classList.remove('cf2-selected');
                el.classList.add('cf2-selected');
            }

            updateButtonLabel();
            closeDropdown();
            applyFilter(selectedIds);
        });
        dropdown.appendChild(el);
    });

    root.appendChild(dropdown);

    // ---------- 7. Применение фильтра ----------
    function applyFilter(values) {
        try {
            const api = visApi();
            if (typeof api.setFilterSelectedValues !== 'function') {
                console.warn('Метод setFilterSelectedValues не найден');
                return;
            }
            // Пустой массив = «Все» / снять фильтр
            const payload = (values || []).map(v => [String(v)]);
            api.setFilterSelectedValues(widgetId, payload, function (resp) {
                // console.log('Фильтр "Страна" применён:', resp);
            });
        } catch (err) {
            console.error('Ошибка применения фильтра:', err);
        }
    }

    // ---------- 8. Открытие/закрытие ----------
    function openDropdown() {
        if (NO_DATA) return;
        dropdown.classList.add('cf2-visible');
        button.classList.add('cf2-open');
    }
    function closeDropdown() {
        dropdown.classList.remove('cf2-visible');
        button.classList.remove('cf2-open');
    }

    button.addEventListener('click', function (e) {
        // Клик по крестику обрабатывается отдельно
        if (e.target === btnClear || btnClear.contains(e.target)) return;
        e.stopPropagation();
        dropdown.classList.contains('cf2-visible')
            ? closeDropdown()
            : openDropdown();
    });

    // Крестик — сбрасывает фильтр
    btnClear.addEventListener('click', function (e) {
        e.stopPropagation();
        selectedIds = [];
        dropdown.querySelectorAll('.cf2-item')
                .forEach(i => i.classList.remove('cf2-selected'));
        allItem.classList.add('cf2-selected');
        updateButtonLabel();
        closeDropdown();
        applyFilter([]);
    });

    document.addEventListener('click', closeDropdown);

    // ---------- 9. Вставка ----------
    container.innerHTML = '';
    container.appendChild(root);
    
    // ---------- 10. Синхронизация с внешними изменениями ----------
    // Уникальный guid для подписки (чтобы не дублировать слушатели)
    const listenerGuid = 'cf-sync-' + widgetId;
    
    try {
        const api = visApi();
        if (typeof api.onSelectedValuesChangedListener === 'function') {
            api.onSelectedValuesChangedListener({
                guid: listenerGuid,
                widgetGuid: widgetId
            }, function(info) {
                // info.selectedValues имеет формат [["значение1"], ["значение2"]]
                // или [] при сбросе. Преобразуем в плоский массив строк.
                const raw = info && Array.isArray(info.selectedValues) 
                    ? info.selectedValues 
                    : [];
                
                // Если формат [["value"]] — разворачиваем; если уже ["value"] — оставляем
                const externalValues = raw.flat 
                    ? raw.flat().map(String) 
                    : [].concat(...raw).map(String);
    
                // Сопоставляем с id элементов фильтра (id могут быть числами)
                const newSelectedIds = items
                    .filter(item => externalValues.includes(String(item.id)))
                    .map(item => item.id);
    
                // Если ничего не изменилось — не трогаем DOM
                if (newSelectedIds.length === selectedIds.length &&
                    newSelectedIds.every((v, i) => String(v) === String(selectedIds[i]))) {
                    return;
                }
    
                // Обновляем локальное состояние
                selectedIds = newSelectedIds;
    
                // Обновляем текст на кнопке
                updateButtonLabel();
    
                // Обновляем выделение в выпадающем списке
                dropdown.querySelectorAll('.cf-item').forEach(function(el) {
                    // Пункт «Все» — без data-value
                    if (!el.dataset.value) {
                        el.classList.toggle('cf-selected', selectedIds.length === 0);
                    } else {
                        const val = el.dataset.value;
                        el.classList.toggle(
                            'cf-selected',
                            selectedIds.some(id => String(id) === String(val))
                        );
                    }
                });
            });
        }
    } catch (err) {
        console.warn('Не удалось подписаться на изменение фильтра:', err);
    }
})();

