    function setFilter(api, guid, values) {
        return new Promise(resolve => {
            try {
                api.setFilterSelectedValues(guid, values, () => resolve());
            } catch (e) {
                console.warn(`Ошибка setFilter для ${guid}:`, e);
                resolve();
            }
            // Страховка: если колбэк не вызовется, продолжаем через 300 мс
