    function findMaxYear(widgetData) {
        if (!widgetData?.data?.rows?.length) {
            console.warn('Нет данных для поиска года, используется', FALLBACK_YEAR);
            return FALLBACK_YEAR;
        }
        const years = [];
        widgetData.data.rows.forEach(row => {
            // В DataFrame фильтра значение лежит в поле .text (а не row[0]!)
            const text = String(row.text ?? row[0] ?? '');
            const matches = text.match(/\b(19|20)\d{2}\b/g);
            if (matches) matches.forEach(y => years.push(parseInt(y, 10)));
        });
        if (!years.length) {
            console.warn('Годы не найдены в значениях фильтра, используется', FALLBACK_YEAR);
            return FALLBACK_YEAR;
        }
        const max = Math.max(...years);
        console.log('🔍 Найденные годы:', [...new Set(years)].sort((a,b)=>b-a), '→ максимум:', max);
