            await setFilter(api, TYPE_FILTER_GUID, [['Год']]);
            let typeSel = await api.getSelectedValues(TYPE_FILTER_GUID);
            if (!typeSel?.[0]?.[0]) {
                console.warn('Формат [["Год"]] не сработал, пробуем [["Год", ""]]');
                await setFilter(api, TYPE_FILTER_GUID, [['Год', '']]);
                typeSel = await api.getSelectedValues(TYPE_FILTER_GUID);
            }
            console.log('📌 Тип периода после установки:', typeSel);

            // 3. Находим максимальный год в «ЗНАЧЕНИИ ПЕРИОДА»
            //    Небольшая пауза, чтобы фильтр успел перестроиться после смены типа
            await new Promise(r => setTimeout(r, 400));
            let maxYear = FALLBACK_YEAR;
            try {
                const wd = await api.getWidgetDataByGuid(VALUE_FILTER_GUID);
                maxYear = findMaxYear(wd);
            } catch (err) {
                console.warn('Не удалось получить данные «Значение периода»:', err);
