// =========================================================
// 1. ФУНКЦИЯ ФОРМАТИРОВАНИЯ (K, M, B)
// =========================================================
function formatValue(val) {
    let v = val;
    if (Array.isArray(v)) v = v[v.length - 1];
    if (v && typeof v === 'object') v = v.value;

    const num = Number(v);
    if (isNaN(num)) return val;

    const abs = Math.abs(num);
    const sign = num < 0 ? '-' : '';
    if (abs >= 1e9) return sign + '$' + (abs / 1e9).toFixed(1).replace(/\.0$/, '') + 'B';
    if (abs >= 1e6) return sign + '$' + (abs / 1e6).toFixed(1).replace(/\.0$/, '') + 'M';
    if (abs >= 1e3) return sign + '$' + (abs / 1e3).toFixed(1).replace(/\.0$/, '') + 'K';
    return sign + '$' + num;
}

// =========================================================
// 2. ПОДСЧЕТ ОБЩЕЙ СУММЫ ДЛЯ ЗАГОЛОВКА
// =========================================================
let totalSum = 0;
if (w.series && w.series[0] && Array.isArray(w.series[0].data)) {
    w.series[0].data.forEach(item => {
        let val = item;
        if (item && typeof item === 'object') val = item.value;
        if (Array.isArray(val)) val = val[val.length - 1];
        totalSum += Number(val) || 0;
    });
}

// =========================================================
// 3. ФОРМАТИРОВАНИЕ ЗАГОЛОВКА (title.text)
// =========================================================
if (w.title && typeof w.title.text === 'string') {
    if (w.title.text.includes('@total')) {
        // Вариант 1: Платформа оставила плейсхолдер @total
        w.title.text = w.title.text.replace(/@total/g, formatValue(totalSum));
    } else {
        // Вариант 2: Платформа уже подставила "сырое" число.
        // Находим все числа в строке и заменяем самое большое (это и есть сумма).
        const matches = w.title.text.match(/\d+(?:\.\d+)?/g);
        if (matches) {
            const maxNum = Math.max(...matches.map(Number));
            if (maxNum > 0) {
                w.title.text = w.title.text.replace(String(maxNum), formatValue(maxNum));
            }
        }
    }
}

// =========================================================
// 4. ФОРМАТИРОВАНИЕ TOOLTIP (для единообразия)
// =========================================================
if (w.tooltip) {
    w.tooltip.formatter = function(params) {
        if (Array.isArray(params)) params = params[0];
        const name = params.name || '';
        const val  = formatValue(params.value);
        const pct  = params.percent != null ? params.percent : null;

        return `
            <div style="font-family: 'Open Sans', Arial, sans-serif; font-size: 13px; line-height: 1.5; color: #1e3d5c;">
                <div style="font-weight: 600; margin-bottom: 4px;">${name}</div>
                <div>Сумма: <b>${val}</b></div>
                ${pct != null ? `<div>Доля: <b>${pct}%</b></div>` : ''}
            </div>
        `;
    };
}

