            'stroke-linecap="round" stroke-linejoin="round"/></svg>';
    root.appendChild(button);

    const btnText    = button.querySelector('.cf2-button-text');
    const btnClear   = button.querySelector('.cf2-clear');
    const btnChevron = button.querySelector('.cf2-chevron');

    // ---------- 5. Пересчёт подписи и видимости крестика ----------
    function updateButtonLabel() {
        if (NO_DATA) {
            btnText.textContent = 'Нет данных';
            btnClear.style.display = 'none';
            btnChevron.style.display = 'none';
            return;
        }
        btnChevron.style.display = '';

        if (selectedIds.length === 0) {
            btnText.textContent = 'Все';
            btnClear.style.display = 'none';
        } else if (selectedIds.length === 1) {
            const c = items.find(i => i.id === selectedIds[0]);
            btnText.textContent = c ? itemName(c) : 'Все';
            btnClear.style.display = 'flex';
        } else {
            btnText.textContent = 'Выбрано: ' + selectedIds.length;
            btnClear.style.display = 'flex';
        }
    }
    updateButtonLabel();

    // ---------- 6. Dropdown ----------
    const dropdown = document.createElement('div');
    dropdown.className = 'cf2-dropdown';

    // Пункт «Все»
    const allItem = document.createElement('div');
    allItem.className = 'cf2-item cf2-all' +
        (selectedIds.length === 0 ? ' cf2-selected' : '');
    allItem.textContent = 'Все';
    allItem.dataset.value = '__ALL__';
    allItem.addEventListener('click', function (e) {
        e.stopPropagation();
        selectedIds = [];
        dropdown.querySelectorAll('.cf2-item')
                .forEach(i => i.classList.remove('cf2-selected'));
        allItem.classList.add('cf2-selected');
        updateButtonLabel();
        closeDropdown();
        applyFilter([]);
    });
    dropdown.appendChild(allItem);

    // Остальные пункты
    items.forEach(function (item) {
        const el = document.createElement('div');
        const isSel = selectedIds.indexOf(item.id) !== -1;
        el.className = 'cf2-item' + (isSel ? ' cf2-selected' : '');
        el.textContent = itemName(item);
        el.dataset.value = item.id;
        el.addEventListener('click', function (e) {
            e.stopPropagation();
            const selNow = selectedIds.indexOf(item.id) !== -1;

            if (selNow) {
                // Унселект — клик по выбранному снимает выбор
                selectedIds = selectedIds.filter(x => x !== item.id);
                el.classList.remove('cf2-selected');
                if (selectedIds.length === 0) allItem.classList.add('cf2-selected');
            } else {
                // Селект — одиночный выбор заменяет предыдущий
                selectedIds = [item.id];
                dropdown.querySelectorAll('.cf2-item')
                        .forEach(i => i.classList.remove('cf2-selected'));
                allItem.classList.remove('cf2-selected');
                el.classList.add('cf2-selected');
