            api.setFilterSelectedValues(widgetId, payload, function (resp) {
                // console.log('Фильтр "Страна" применён:', resp);
            });
        } catch (err) {
            console.error('Ошибка применения фильтра:', err);
        }
    }

    // ---------- 8. Открытие/закрытие ----------
    function openDropdown() {
        if (NO_DATA) return;
        dropdown.classList.add('cf2-visible');
        button.classList.add('cf2-open');
    }
    function closeDropdown() {
        dropdown.classList.remove('cf2-visible');
        button.classList.remove('cf2-open');
    }

    button.addEventListener('click', function (e) {
        // Клик по крестику обрабатывается отдельно
        if (e.target === btnClear || btnClear.contains(e.target)) return;
        e.stopPropagation();
        dropdown.classList.contains('cf2-visible')
            ? closeDropdown()
            : openDropdown();
    });

    // Крестик — сбрасывает фильтр
    btnClear.addEventListener('click', function (e) {
        e.stopPropagation();
        selectedIds = [];
        dropdown.querySelectorAll('.cf2-item')
                .forEach(i => i.classList.remove('cf2-selected'));
        allItem.classList.add('cf2-selected');
        updateButtonLabel();
        closeDropdown();
        applyFilter([]);
    });

    document.addEventListener('click', closeDropdown);

    // ---------- 9. Вставка ----------
    container.innerHTML = '';
    container.appendChild(root);
    
    // ---------- 10. Синхронизация с внешними изменениями ----------
    // Уникальный guid для подписки (чтобы не дублировать слушатели)
    const listenerGuid = 'cf-sync-' + widgetId;
    
    try {
        const api = visApi();
        if (typeof api.onSelectedValuesChangedListener === 'function') {
            api.onSelectedValuesChangedListener({
                guid: listenerGuid,
                widgetGuid: widgetId
            }, function(info) {
                // info.selectedValues имеет формат [["значение1"], ["значение2"]]
                // или [] при сбросе. Преобразуем в плоский массив строк.
                const raw = info && Array.isArray(info.selectedValues) 
                    ? info.selectedValues 
                    : [];
                
                // Если формат [["value"]] — разворачиваем; если уже ["value"] — оставляем
                const externalValues = raw.flat 
                    ? raw.flat().map(String) 
                    : [].concat(...raw).map(String);
    
                // Сопоставляем с id элементов фильтра (id могут быть числами)
                const newSelectedIds = items
                    .filter(item => externalValues.includes(String(item.id)))
                    .map(item => item.id);
    
                // Если ничего не изменилось — не трогаем DOM
                if (newSelectedIds.length === selectedIds.length &&
                    newSelectedIds.every((v, i) => String(v) === String(selectedIds[i]))) {
                    return;
                }
    
                // Обновляем локальное состояние
                selectedIds = newSelectedIds;
    
                // Обновляем текст на кнопке
                updateButtonLabel();
    
                // Обновляем выделение в выпадающем списке
                dropdown.querySelectorAll('.cf-item').forEach(function(el) {
                    // Пункт «Все» — без data-value
                    if (!el.dataset.value) {
                        el.classList.toggle('cf-selected', selectedIds.length === 0);
                    } else {
                        const val = el.dataset.value;
                        el.classList.toggle(
                            'cf-selected',
                            selectedIds.some(id => String(id) === String(val))
                        );
                    }
                });
            });
        }
    } catch (err) {
        console.warn('Не удалось подписаться на изменение фильтра:', err);
    }
})();

