                    ? info.selectedValues 
                    : [];
                
                // Если формат [["value"]] — разворачиваем; если уже ["value"] — оставляем
                const externalValues = raw.flat 
                    ? raw.flat().map(String) 
                    : [].concat(...raw).map(String);
    
                // Сопоставляем с id элементов фильтра (id могут быть числами)
                const newSelectedIds = items
                    .filter(item => externalValues.includes(String(item.id)))
                    .map(item => item.id);
    
                // Если ничего не изменилось — не трогаем DOM
                if (newSelectedIds.length === selectedIds.length &&
                    newSelectedIds.every((v, i) => String(v) === String(selectedIds[i]))) {
                    return;
                }
    
                // Обновляем локальное состояние
                selectedIds = newSelectedIds;
    
                // Обновляем текст на кнопке
                updateButtonLabel();
    
                // Обновляем выделение в выпадающем списке
                dropdown.querySelectorAll('.cf-item').forEach(function(el) {
                    // Пункт «Все» — без data-value
                    if (!el.dataset.value) {
