    infoEl.addEventListener('mouseleave', () => tooltipEl.classList.remove('visible'));
    infoEl.appendChild(tooltipEl);

    container.appendChild(header);
    container.appendChild(infoEl);

    // ---------- 5. Умный подсчет и обновление счетчика ----------

    const counterEl = () => document.getElementById(`counter-${widgetId}`);
    const isValidCount = (v) => typeof v === 'number' && isFinite(v) && v >= 0;

    // Проверяет, что грид не в состоянии загрузки
    const isGridLoading = () => {
        return !!container.querySelector('.dx-loadpanel, .dx-datagrid-loading, .dx-loadpanel-content');
    };

    // Читает количество из доступных источников. Возвращает число или null (неизвестно).
    function readCount() {
        const ds = w.dataGridOptions && w.dataGridOptions.dataSource;

        // Вариант 1: dataSource._totalCount (только валидные >= 0; -1 = "ещё не посчитано")
        if (ds && isValidCount(ds._totalCount)) {
            return ds._totalCount;
        }

        // Вариант 2: dataSource.items.length
        if (ds && Array.isArray(ds.items)) {
            return ds.items.length;
        }

        // Вариант 3: корень items
        if (w.dataGridOptions && Array.isArray(w.dataGridOptions.items)) {
            return w.dataGridOptions.items.length;
        }

        return null;
    }

    // Пытается обновить счётчик. Возвращает true, если удалось записать валидное значение.
    function updateCounter() {
        const el = counterEl();
        if (!el) return false;

        let count = readCount();

        // Fallback через DOM
        if (count === null || count === 0) {
            if (isGridLoading()) return false; // ждём окончания загрузки
            const rows = container.querySelectorAll('.dx-data-row');
            if (rows.length > 0) {
                count = rows.length;
            } else if (count === null) {
                count = 0;
            }
        }

        // Пишем только валидные числа
        if (!isValidCount(count)) return false;

        el.innerHTML = `Сделок в текущей выборке: <b>${count}</b>`;
        return true;
    }

    // Первичный опрос на старте — пока грид не смонтирован.
    // Не выходим по таймауту «вслепую», а ждём, пока не появится валидное значение.
    let attempts = 0;
    const maxAttempts = 100; // ~15 секунд с интервалом 150мс
    const counterInterval = setInterval(() => {
        if (updateCounter() || ++attempts >= maxAttempts) {
            clearInterval(counterInterval);
        }
    }, 150);

    // ---------- 6. Реактивное обновление через события DataGrid ----------
    function attachCounterToGrid() {
        const gridEl = container.querySelector('.dx-datagrid');
        if (!gridEl) return false;
        if (!window.DevExpress || !DevExpress.ui || !DevExpress.ui.dxDataGrid) return false;

        const grid = DevExpress.ui.dxDataGrid.getInstance(gridEl);
        if (!grid) return false;
        if (grid.__ddcCounterAttached) return true;

        grid.__ddcCounterAttached = true;

        // Обновление при любой готовности контента: загрузка, фильтр, пагинация и т.д.
        grid.on('contentReady', updateCounter);

        // Мгновенная реакция на смену dataSource/фильтров (серия вызовов с задержками,
        // т.к. _totalCount обновится не сразу).
        grid.on('optionChanged', (e) => {
            if (e.name === 'dataSource' ||
                e.name === 'filterValue' ||
                e.name === 'filterValues' ||
                e.name === 'searchValue') {
                setTimeout(updateCounter, 100);
                setTimeout(updateCounter, 500);
                setTimeout(updateCounter, 1500);
            }
        });

        // Подстраховка через сам DataSource
        const ds = grid.getDataSource && grid.getDataSource();
        if (ds && typeof ds.on === 'function') {
            ds.on('changed', updateCounter);
            ds.on('loadingChanged', (e) => {
                if (!e || !e.isLoading) updateCounter();
            });
        }

        updateCounter();
        return true;
    }

