// ---- Функция применения классов к элементам ----
function updateWidgetClasses() {
    const activeIdx = window.__groupToggleState.activeGroup;
    
    buttonsArr.forEach((btn, gIdx) => {
        // Обновляем вид кнопок
        if (gIdx === activeIdx) {
            btn.element.classList.add('chart-button-active');
        } else {
            btn.element.classList.remove('chart-button-active');
        }
        
        // Обновляем классы самих виджетов
        btn.items.forEach(item => {
            const el = document.getElementById(item.id);
            if (!el) return;
            
            if (gIdx === activeIdx) {
                el.classList.remove('vis-force-hidden');
                el.classList.add(item.posClass);
            } else {
                el.classList.remove(item.posClass);
                el.classList.add('vis-force-hidden');
            }
        });
    });
}

// ---- Наблюдатель за сбросом классов (Защита от Visiology) ----
// Visiology пытается сбросить классы, мы их мгновенно возвращаем
const classObserver = new MutationObserver((mutations) => {
    const activeIdx = window.__groupToggleState.activeGroup;
    let needsFix = false;
    
    for (let m of mutations) {
        const el = m.target;
        
        // Находим, к какой группе относится виджет
        let gIdx = -1;
        let item = null;
        for (let i = 0; i < buttonsArr.length; i++) {
            const found = buttonsArr[i].items.find(it => document.getElementById(it.id) === el);
            if (found) { gIdx = i; item = found; break; }
        }
        
        if (gIdx !== -1 && item) {
            if (gIdx === activeIdx) {
                if (!el.classList.contains(item.posClass) || el.classList.contains('vis-force-hidden')) {
                    el.classList.remove('vis-force-hidden');
                    el.classList.add(item.posClass);
                }
            } else {
                if (!el.classList.contains('vis-force-hidden') || el.classList.contains(item.posClass)) {
                    el.classList.remove(item.posClass);
                    el.classList.add('vis-force-hidden');
                }
            }
        }
    }
});

function attachObservers() {
    classObserver.disconnect();
    buttonsArr.forEach(btn => {
        btn.items.forEach(item => {
            const el = document.getElementById(item.id);
            if (el) {
                classObserver.observe(el, { attributes: true, attributeFilter: ['class', 'style'] });
            }
        });
    });
}

// ---- onClick ----
buttonsArr.forEach((btn, index) => {
    btn.element.onclick = function () {
        window.__groupToggleState.activeGroup = index;
        updateWidgetClasses();
        attachObservers(); // Переподключаем обсервер на случай, если DOM обновился
    };
});

// ---- Инициализация ----
updateWidgetClasses();
attachObservers();

// ---- Легкая проверка (раз в 1 сек), если Visiology полностью пересоздала DOM-элементы ----
