    // =========================================================
    // 1. Исходные данные
    // =========================================================
    const mainSeries = w.series[0];
    const originalData = mainSeries.data;

    function getValue(point) {
        let value = point;
        if (point && typeof point === "object") value = point.value;
        if (Array.isArray(value)) value = value[value.length - 1];
        if (value === null || value === undefined || value === "") return 0;
        const result = Number(value);
        return Number.isFinite(result) ? result : 0;
    }

    function getName(point, index) {
        if (point && typeof point === "object") {
            if (point.name != null && point.name !== "") return String(point.name);
            if (point.id != null && point.id !== "") return String(point.id);
        }
        if (Array.isArray(w.yAxis?.data) && w.yAxis.data[index] != null) {
            return String(w.yAxis.data[index]);
        }
        return String(index + 1);
    }

    function formatValue(value) {
        return new Intl.NumberFormat("ru-RU", { maximumFractionDigits: 2 }).format(value);
    }

    function escapeHTML(value) {
        return String(value).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&#39;");
    }

    // ---- СОРТИРОВКА по убыванию значения ----
    // Сортируем сразу "пары" (оригинальная точка + имя + значение),
    // затем раскладываем обратно в rows и в w.series[0].data,
    // чтобы подписи и длины баров остались синхронными.
    const indexed = originalData.map((point, index) => ({
        original: point,
