    function readDateDirect(object) {
        if (!object || typeof object !== "object") return null;
        const candidates = [
            object, object.DataGridOptions, object.dataGridOptions, object.options,
            object.options?.DataGridOptions, object.options?.dataGridOptions
        ];
        for (const candidate of candidates) {
            const value = candidate?.dataSource?._items?.[0]?.SelectedPeriodEnd;
            if (value !== undefined && value !== null && value !== "") return value;
        }
        return null;
    }

    function findDateDeep(root, maxDepth = 6) {
        const direct = readDateDirect(root);
        if (direct != null) return direct;
        if (!root || typeof root !== "object") return null;
        const queue = [{ object: root, depth: 0 }];
        const visited = new WeakSet();
        let checked = 0;
        while (queue.length && checked < 1500) {
            const item = queue.shift();
            const object = item.object;
            if (!object || typeof object !== "object") continue;
            if (visited.has(object)) continue;
            visited.add(object);
            checked++;
            const value = readDateDirect(object);
            if (value != null) return value;
            if (item.depth >= maxDepth || object.nodeType) continue;
            let keys;
            try { keys = Object.keys(object); } catch (_) { continue; }
            for (const key of keys) {
                if (["parent", "parentNode", "ownerDocument", "element", "children"].includes(key)) continue;
                let child;
                try { child = object[key]; } catch (_) { continue; }
                if (child && typeof child === "object") {
