(function () {
    const widgetId = w.general.renderTo;
    const DATE_WIDGET_ID = "cf9ad8e5bf744ca1a4c4dad50b2f2372";

    const container = document.getElementById(widgetId) || document.querySelector(`[id="${widgetId}"]`);
    if (!container) return;
    if (!w.series || !w.series[0] || !Array.isArray(w.series[0].data)) return;

    // =========================================================
    // 1. Получение SelectedPeriodEnd
    // =========================================================
    let cachedPeriodEnd = null;
    let isFetchingDate = false;

    function readDateDirect(object) {
        if (!object || typeof object !== "object") return null;
        const candidates = [
            object, object.w, object.DataGridOptions, object.w?.DataGridOptions,
            object.dataGridOptions, object.w?.dataGridOptions, object.options,
            object.options?.DataGridOptions, object.options?.dataGridOptions
        ];
        for (const candidate of candidates) {
            if (!candidate) continue;
            const value = candidate?.dataSource?._items?.[0]?.SelectedPeriodEnd;
            if (value !== undefined && value !== null && value !== "") return value;
        }
        return null;
    }

    function findDateDeep(root, maxDepth = 10) {
        const direct = readDateDirect(root);
        if (direct != null) return direct;
        if (!root || typeof root !== "object") return null;
        const queue = [{ object: root, depth: 0 }];
        const visited = new WeakSet();
        let checked = 0;
        while (queue.length && checked < 5000) {
            const item = queue.shift();
            const object = item.object;
            if (!object || typeof object !== "object") continue;
            if (visited.has(object)) continue;
            visited.add(object);
            checked++;
            const value = readDateDirect(object);
            if (value != null) return value;
            if (item.depth >= maxDepth || object.nodeType) continue;
            let keys;
            try { keys = Object.keys(object); } catch (_) { continue; }
            for (const key of keys) {
                if (["parent", "parentNode", "ownerDocument", "element", "children", "_owner", "stateNode"].includes(key)) continue;
                let child;
                try { child = object[key]; } catch (_) { continue; }
                if (child && typeof child === "object") {
                    queue.push({ object: child, depth: item.depth + 1 });
                }
            }
        }
        return null;
    }

    function getPeriodEndRaw() {
        if (cachedPeriodEnd) return cachedPeriodEnd;
        try {
            if (typeof DataGridOptions !== "undefined") {
                const value = readDateDirect(DataGridOptions);
                if (value != null) { cachedPeriodEnd = value; return value; }
            }
        } catch (_) {}
        try {
            if (window.DataGridOptions) {
                const value = readDateDirect(window.DataGridOptions);
                if (value != null) { cachedPeriodEnd = value; return value; }
            }
        } catch (_) {}
        try {
            const gridElement = document.getElementById("dataGridContainer_" + DATE_WIDGET_ID) || document.getElementById(DATE_WIDGET_ID);
            if (gridElement) {
                const candidates = [gridElement.DataGridOptions, gridElement.dataGridOptions, gridElement.__DataGridOptions, gridElement.ej2_instances?.[0]];
                for (const candidate of candidates) {
                    const value = findDateDeep(candidate, 4);
                    if (value != null) { cachedPeriodEnd = value; return value; }
                }
            }
        } catch (_) {}

        if (!isFetchingDate && typeof visApi === "function") {
            isFetchingDate = true;
            try {
                const sourceWidget = visApi().getWidgetByGuid(DATE_WIDGET_ID);
                if (sourceWidget && typeof sourceWidget.then === "function") {
                    sourceWidget.then(function (object) {
                        const value = findDateDeep(object);
                        if (value != null) cachedPeriodEnd = value;
                        isFetchingDate = false;
                    }).catch(function (error) {
                        console.warn("Ошибка даты:", error);
                        isFetchingDate = false;
                    });
                } else {
                    const value = findDateDeep(sourceWidget);
                    if (value != null) { cachedPeriodEnd = value; return value; }
                    isFetchingDate = false;
                }
            } catch (error) {
                console.warn("Ошибка чтения даты:", error);
                isFetchingDate = false;
            }
        }
        return cachedPeriodEnd;
    }

    function formatDate(value) {
        if (value === null || value === undefined || value === "") return "—";
        if (typeof value === "string") {
            const match = value.match(/^(\d{4})-(\d{2})-(\d{2})/);
            if (match) return `${match[3]}.${match[2]}.${match[1]}`;
        }
        const date = value instanceof Date ? value : new Date(value);
        if (Number.isNaN(date.getTime())) return String(value);
        const day = String(date.getDate()).padStart(2, "0");
        const month = String(date.getMonth() + 1).padStart(2, "0");
        return `${day}.${month}.${date.getFullYear()}`;
    }

    // =========================================================
    // 2. ОБРАБОТКА ДАННЫХ
    // =========================================================
    const periodEndRaw = getPeriodEndRaw();
    const periodEndDate = periodEndRaw ? new Date(periodEndRaw) : new Date("9999-12-31");
    const allowedStages = ["C1:NEW", "C1:PREPARATION", "C1:PREPAYMENT_INVOICE", "C1:EXECUTING"];

    let rawStrings = [];
    if (Array.isArray(w.series[0].data)) {
        rawStrings = w.series[0].data.map(item => {
             if (typeof item === 'string') return item;
             if (item && typeof item === 'object') return item.id || item.name || "";
             return "";
        }).filter(s => s);
    }

    const latestStagesMap = new Map();

    rawStrings.forEach(str => {
        if (typeof str !== 'string') return;
        
        let parts = str.split(' - ');
        if (parts.length < 4) return;

        const dateStr = parts[parts.length - 1].trim();
        const stageId = parts[parts.length - 2].trim();
        const dealId = parts[parts.length - 3].trim();
        const stageName = parts.slice(0, -3).join(' - ').trim(); 

        const stageDate = new Date(dateStr.replace(' ', 'T'));
        if (isNaN(stageDate.getTime())) return;

        if (stageDate > periodEndDate) return;

        const existing = latestStagesMap.get(dealId);
        if (!existing || stageDate > existing.date) {
            latestStagesMap.set(dealId, { dealId, stageId, stageName, date: stageDate });
        }
    });

    // ИСПРАВЛЕНИЕ: Группируем по stageName, а не по stageId. 
    // Это гарантирует, что сумма на баре совпадет с результатом фильтрации по имени.
    const stageCounts = new Map();
    latestStagesMap.forEach(record => {
        if (allowedStages.includes(record.stageId)) {
            const name = record.stageName || record.stageId;
            if (!stageCounts.has(name)) {
                stageCounts.set(name, { id: record.stageId, name: name, value: 0 });
            }
            stageCounts.get(name).value += 1;
        }
    });

    let rows = Array.from(stageCounts.values());
    rows.sort((a, b) => b.value - a.value);

    const count = rows.length;
    if (count === 0) {
        container.innerHTML = '<div style="padding:20px;color:#718096;font-family:\'Open Sans\',Arial,sans-serif;">Нет данных за выбранный период</div>';
        return;
    }

    const maxValue = Math.max(1, ...rows.map(row => row.value));
    const axisMax = maxValue * 1.16;

    function formatValue(value) {
        return new Intl.NumberFormat("ru-RU", { maximumFractionDigits: 2 }).format(value);
    }

    function escapeHTML(value) {
        return String(value).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&#39;");
    }

    // =========================================================
    // 3. Константы layout
    // =========================================================
    const BAR_HEIGHT      = 24;
    const GAP             = 10;
    const CATEGORY_HEIGHT = BAR_HEIGHT + GAP;
    const HEADER_HEIGHT   = 60;
    const exactChartHeight = count * CATEGORY_HEIGHT;

    // =========================================================
    // 4. Стили контейнера
    // =========================================================
