    // ══════════════════════════════════════════════════════════
    // СОСТОЯНИЕ
    // ══════════════════════════════════════════════════════════
    if (typeof widget.buttonClicked === 'undefined') widget.buttonClicked = 0;
    if (typeof widget.filterInfo === 'undefined') widget.filterInfo = 0;

    const entries = new Map();
    const lastValues = new Map();
    const subscribed = new Set();
    const recentlyUpdated = new Map();

    let lastSig = '';
    let renderTimer = null;
    let rendering = false;

    const RECENT_MS = 500;

    // ══════════════════════════════════════════════════════════
    // УТИЛИТЫ
    // ══════════════════════════════════════════════════════════
    function escapeHtml(s) {
        return String(s).replace(/[&<>"']/g, function (c) {
            return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
        });
    }

    function normalize(v) {
        if (!Array.isArray(v)) return [];
        return v.map(item => {
            if (Array.isArray(item)) return item.map(String);
            if (item == null) return [''];
            if (typeof item === 'object') return [String(item.id ?? item.value ?? item.text ?? '')];
            return [String(item)];
        }).filter(a => a.length && a.some(x => x !== ''));
    }

    function valuesDisplay(values) {
        if (!Array.isArray(values) || !values.length) return '';
        return values.map(v => Array.isArray(v) ? v.join(' / ') : String(v)).join(', ');
    }

    // ── Поиск DOM-элемента виджета по GUID ─────────────────────
    function findWidgetEl(doc, guid) {
        if (!doc) return null;
        const g = String(guid);

        let el = null;
        try { el = doc.getElementById('widget-' + g); } catch (e) {}
        if (el && el.classList && el.classList.contains('va-widget')) return el;

        try { el = doc.getElementById(g); } catch (e) {}
        if (el && el.classList && el.classList.contains('va-widget')) return el;

        // скан по .va-widget
        let all;
        try { all = doc.querySelectorAll('.va-widget'); } catch (e) { return null; }
        for (const w of all) {
            const wId = w.id || '';
            if (wId === 'widget-' + g || wId === g) return w;
            const body = w.querySelector('.va-widget-body');
            if (body) {
                const bodyId = (body.id || '').replace(/^widget-/, '');
                if (bodyId === g) return w;
            }
        }
        return null;
    }

    // ── Заголовок виджета ──────────────────────────────────────
    function getTitle(guid) {
        const docsToTry = [];
        try {
            if (window.parent && window.parent.document) docsToTry.push(window.parent.document);
        } catch (e) {}
        try { docsToTry.push(document); } catch (e) {}

        for (const doc of docsToTry) {
            const el = findWidgetEl(doc, guid);
            if (!el) continue;

            // 1) точные селекторы заголовка
            const titleSelectors = [
                '.va-widget-title',
                '.va-widget-header-title',
                '.widget-title',
                '[class*="widget-title"]',
            ];
            for (const sel of titleSelectors) {
                let node;
                try { node = el.querySelector(sel); } catch (e) {}
                if (node) {
                    const t = (node.textContent || '').trim().replace(/\s+/g, ' ');
                    if (t) return t;
                }
            }

            // 2) целиком из .va-widget-header
            const headerEl = el.querySelector('.va-widget-header, [class*="widget-header"]');
            if (headerEl) {
                const t = (headerEl.textContent || '').trim().replace(/\s+/g, ' ');
                if (t) return t;
            }
        }

        // 3) через getWidgets()
        try {
            const list = visApi().getWidgets() || [];
            for (const it of list) {
                const g = it?.widgetState?.guid || it?.guid || it?.id;
                if (String(g) === String(guid)) {
                    const t = it?.widgetState?.title
                           || it?.widgetState?.name
                           || it?.widgetState?.caption
                           || it?.title
                           || it?.name;
                    if (t) return String(t).trim();
                }
            }
        } catch (e) {}

        // 4) fallback
        return guid.slice(-8);
    }

    function getType(guid) {
        const docsToTry = [];
        try {
            if (window.parent && window.parent.document) docsToTry.push(window.parent.document);
        } catch (e) {}
        try { docsToTry.push(document); } catch (e) {}

        for (const doc of docsToTry) {
            const el = findWidgetEl(doc, guid);
            if (!el) continue;
            if (el.querySelector('[class*="calendar"]')) return 'calendar';
            if (el.querySelector('[class*="filter"]')) return 'filter';
            return 'widget';
        }
        return 'filter';
    }

    // ══════════════════════════════════════════════════════════
    // ИНИЦИАЛИЗАЦИЯ
    // ══════════════════════════════════════════════════════════
    function readInitial(guid) {
        let norm = [];
        try { norm = normalize(visApi().getSelectedValues(guid)); } catch (e) {}
        entries.set(guid, {
            id: guid,
            header: getTitle(guid),
            filter: norm,
            type: getType(guid),
        });
        if (norm.length) lastValues.set(guid, norm);
    }

    function refreshTitles() {
        let changed = false;
        GUIDs.forEach(guid => {
            const entry = entries.get(guid);
            if (!entry) return;
            const t = getTitle(guid);
            if (t && t !== entry.header) {
                entry.header = t;
                changed = true;
            }
        });
        return changed;
    }

    function subscribe(guid) {
        if (subscribed.has(guid)) return;
        try {
            visApi().onSelectedValuesChangedListener({
                guid: 'fw-sub-' + uid + '-' + guid,
                widgetGuid: guid,
            }, function (info) {
                const now = Date.now();
                if (now - (recentlyUpdated.get(guid) || 0) < RECENT_MS) return;

                const values = info && Array.isArray(info.selectedValues)
                    ? normalize(info.selectedValues)
                    : [];

                const entry = entries.get(guid);
                if (!entry) return;
                if (JSON.stringify(entry.filter) === JSON.stringify(values)) return;

                entry.filter = values;
                if (values.length) lastValues.set(guid, values);
                scheduleRender();
            });
            subscribed.add(guid);
        } catch (e) {
            console.warn('[FW] subscribe failed:', guid, e);
        }
    }

    // ══════════════════════════════════════════════════════════
    // СБОРКА И РЕНДЕР
    // ══════════════════════════════════════════════════════════
    function buildItems() {
        const items = [];
        GUIDs.forEach(guid => {
            const entry = entries.get(guid);
            if (!entry) return;
            const hasValue = entry.filter.length > 0;
            const history = lastValues.get(guid) || [];
            if (!hasValue && !history.length) return;

            items.push({
                header: entry.header,
                value: hasValue ? valuesDisplay(entry.filter) : valuesDisplay(history),
                filter: hasValue ? entry.filter : history,
                id: guid,
                isOn: hasValue,
                type: entry.type,
            });
        });
        return items;
    }

    function buildTable(items) {
        let h = '<table class="filter-info"><thead><tr>';
        h += '<th>Фильтр</th><th colspan="2">Значение</th></tr></thead><tbody>';

        if (!items.length) {
            const reason = GUIDs.length
                ? 'Нет активных фильтров'
                : 'Не заданы widget_guids в настройках';
            h += `<tr><td colspan="3" class="empty">${reason}</td></tr>`;
        } else {
            items.forEach((it, i) => {
                const st = it.isOn ? 'on' : 'off';
                h += `<tr>`;
                h += `<td title="${escapeHtml(it.id)}">${escapeHtml(it.header)}</td>`;
                h += `<td>${escapeHtml(it.value)}</td>`;
                h += `<td>`;
                h += `<div class="onoffswitch"><label class="onoffswitch-label" `;
                h += `data-widget-id="${it.id}" data-widget-type="${it.type}" id="filter-info-${i}">`;
                h += `<div class="onoffswitch-inner ${st}"></div>`;
                h += `<div class="onoffswitch-switch ${st}"></div>`;
                h += `</label></div></td></tr>`;
            });
        }

        h += '</tbody></table>';
        return h;
    }

    function ensureShell() {
        let button = widget.querySelector('#btn-filter');
        if (!button) {
            button = document.createElement('button');
            button.classList.add('btn-class');
            button.id = 'btn-filter';
            button.innerHTML =
                '<span class="fw-btn-icon"></span>' + chevronSvg;
            widget.appendChild(button);
            button.addEventListener('click', onButtonClick);
        }
        let area = widget.querySelector('.btn-filter-area-class');
        if (!area) {
            area = document.createElement('div');
            area.classList.add('btn-filter-area-class');
            area.addEventListener('click', onToggle);
            button.after(area);
        }
    }

    function render() {
        if (rendering) return;
        rendering = true;
        try {
            ensureShell();
            const button = widget.querySelector('#btn-filter');
            const area = widget.querySelector('.btn-filter-area-class');
            const iconEl = button.querySelector('.fw-btn-icon');

            const items = buildItems();
            // ⚠ header включён в сигнатуру — иначе переименование не отрисуется
            const sig = items
                .map(i => i.id + '=' + i.header + '=' + i.value + '=' + i.isOn)
                .join('|');

            const icon = items.some(i => i.isOn) ? icon_filled : icon_unfilled;
            if (iconEl && iconEl.getAttribute('data-icon') !== icon) {
                iconEl.innerHTML = icon;
                iconEl.setAttribute('data-icon', icon);
            }

            button.classList.toggle('open', !!widget.buttonClicked);

            if (widget.buttonClicked) {
                if (sig !== lastSig) {
                    lastSig = sig;
                    area.innerHTML = buildTable(items);
                    area.filterInfo = items;
                }
                area.style.visibility = 'visible';
            } else {
                area.style.visibility = 'hidden';
            }
        } catch (e) {
            console.warn('[FW] render error:', e);
        } finally {
            rendering = false;
        }
    }

    function scheduleRender() {
        if (renderTimer) return;
        renderTimer = setTimeout(() => {
            renderTimer = null;
            render();
        }, 100);
    }

    // ══════════════════════════════════════════════════════════
    // ОБРАБОТЧИКИ
    // ══════════════════════════════════════════════════════════
    function onButtonClick() {
        widget.buttonClicked = widget.buttonClicked ? 0 : 1;
        if (widget.buttonClicked) lastSig = '';
        render();
    }

    function onToggle(event) {
        const label = event.target.closest('.onoffswitch-label');
        if (!label) return;
        const guid = label.dataset.widgetId;
        if (!guid) return;

        const entry = entries.get(guid);
        if (!entry) return;

        const sw = label.querySelector('.onoffswitch-switch');
        const wasOn = sw && sw.classList.contains('on');
        const willBeOn = !wasOn;

        for (const c of label.children) {
            if (c.classList.contains('on')) { c.classList.remove('on'); c.classList.add('off'); }
            else if (c.classList.contains('off')) { c.classList.remove('off'); c.classList.add('on'); }
        }

        const valuesToApply = willBeOn
            ? (lastValues.get(guid) || entry.filter || [])
            : [];

        entry.filter = valuesToApply;
        if (valuesToApply.length) lastValues.set(guid, valuesToApply);
        recentlyUpdated.set(guid, Date.now());

        try {
            visApi().setFilterSelectedValues(guid, valuesToApply);
        } catch (e) {
            console.warn('[FW] setFilter error:', e);
            entry.filter = wasOn ? (lastValues.get(guid) || []) : [];
            for (const c of label.children) {
                if (c.classList.contains('on')) { c.classList.remove('on'); c.classList.add('off'); }
                else if (c.classList.contains('off')) { c.classList.remove('off'); c.classList.add('on'); }
            }
        }

        if (!willBeOn && entry.type === 'widget') {
            setTimeout(() => {
                lastValues.delete(guid);
                if (Array.isArray(widget.filterInfo)) {
                    const i = widget.filterInfo.findIndex(x => x.id === guid);
                    if (i !== -1) widget.filterInfo.splice(i, 1);
                }
                lastSig = '';
                scheduleRender();
            }, 500);
        }

        lastSig = '';
        scheduleRender();
    }

    // ══════════════════════════════════════════════════════════
    // СТАРТ
    // ══════════════════════════════════════════════════════════
    GUIDs.forEach(guid => {
        readInitial(guid);
        subscribe(guid);
    });
    render();

    try {
        visApi().onAllWidgetsLoadedListener({ guid: 'fw-loaded-' + uid }, function () {
            const now = Date.now();
            let changed = false;

            // 1) обновить заголовки (parent DOM может прогрузиться позже)
            if (refreshTitles()) changed = true;

            // 2) точечно обновить значения (без перечтения только что тоггнутых)
            GUIDs.forEach(guid => {
                if (now - (recentlyUpdated.get(guid) || 0) < RECENT_MS) return;
                try {
                    const norm = normalize(visApi().getSelectedValues(guid));
                    const entry = entries.get(guid);
                    if (!entry) return;
                    if (JSON.stringify(entry.filter) === JSON.stringify(norm)) return;
                    entry.filter = norm;
                    if (norm.length) lastValues.set(guid, norm);
                    changed = true;
                } catch (e) {}
            });

            if (changed) scheduleRender();
        });
    } catch (e) {}
})();
